
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_tau_hcth_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_tau_hcth", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.658609541657312e+00, -3.586998506273898e+00, -3.486803262796538e+00, -3.348334283516373e+00, -3.160370566063132e+00, -2.911753734004575e+00, -2.594774786352918e+00, -2.209511010116235e+00, -1.765890702053989e+00, -1.313930742303035e+00, -9.284869839232031e-01, -6.032936174170981e-01, -5.155069650900068e-01, -4.222719397850888e-01, -3.063239827327908e-01, -2.124377009045700e-01, -1.519881403351819e-01, -6.731645559039685e-02, -1.523176787270515e-02, -1.716629225776973e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


